<?php
declare(strict_types=1);
final class TaskApiController{
 public function __construct(private TaskApplicationService$app,private int$userId,private bool$featureEnabled,private ?TaskRecurrenceAdministration$recurrence=null){}
 public function handle(string$method,array$query,array$body,array$headers=[]):TaskApiResponse{
  if($this->userId<=0)return TaskApiResponse::error('unauthorized',401);
  try{$action=(string)($method==='GET'?($query['action']??'list'):($body['action']??''));if($method==='GET'){if($action==='list')return TaskApiResponse::ok($this->app->list($this->userId,$query));if($action==='detail')return TaskApiResponse::ok($this->app->detail($this->userId,(string)($query['task']??'')));if(str_starts_with($action,'recurrence_')){if(!$this->featureEnabled||$this->recurrence===null)throw new TaskNotFoundException('not_found');if($action==='recurrence_list')return TaskApiResponse::ok($this->recurrence->recurrenceList($this->userId,$query));if($action==='recurrence_detail')return TaskApiResponse::ok($this->recurrence->recurrenceDetail($this->userId,(string)($query['rule']??'')));}throw new TaskNotFoundException('not_found');}
   if($method!=='POST')return TaskApiResponse::error('method_not_allowed',405);if(!$this->featureEnabled)throw new TaskNotFoundException('not_found');CsrfGuard::assertSessionToken((string)($headers['x-csrf-token']??''));if($action==='autonomy_policy_update')return TaskApiResponse::ok($this->app->updateAutonomyPolicy($this->userId,$body));if(in_array($action,['autonomy_pause','autonomy_resume','autonomy_stop'],true))return TaskApiResponse::ok($this->app->autonomyTransition($this->userId,$body,$action));if($action==='autonomy_cycle_start')return TaskApiResponse::ok($this->app->startAutonomyCycle($this->userId,$body));if($action==='autonomy_root_enroll')return TaskApiResponse::ok($this->app->enrollAutonomyRoot($this->userId,$body));if($action==='autonomy_continuation_answer')return TaskApiResponse::ok($this->app->answerAutonomyContinuation($this->userId,$body));if(in_array($action,['autonomy_proposal_approve','autonomy_proposal_reject'],true))return TaskApiResponse::ok($this->app->decideAutonomyProposal($this->userId,$body,$action==='autonomy_proposal_approve'));if(in_array($action,['autonomy_replan_approve','autonomy_replan_reject'],true))return TaskApiResponse::ok($this->app->decideAutonomyReplan($this->userId,$body,$action==='autonomy_replan_approve'));if($action==='create')return TaskApiResponse::ok($this->app->create($this->userId,$body),201);if($action==='reschedule')return TaskApiResponse::ok($this->app->reschedule($this->userId,$body));if($action==='cancel')return TaskApiResponse::ok($this->app->cancel($this->userId,$body));if($action==='approve')return TaskApiResponse::ok($this->app->approve($this->userId,$body));if($action==='reject')return TaskApiResponse::ok($this->app->reject($this->userId,$body));if($action==='approve_step')return TaskApiResponse::ok($this->app->approveStep($this->userId,$body));if($action==='reject_step')return TaskApiResponse::ok($this->app->rejectStep($this->userId,$body));if($action==='approve_tool')return TaskApiResponse::ok($this->app->approveTool($this->userId,$body));if($action==='reject_tool')return TaskApiResponse::ok($this->app->rejectTool($this->userId,$body));if($action==='retry')return TaskApiResponse::ok($this->app->retry($this->userId,$body));if($action==='add_dependency')return TaskApiResponse::ok($this->app->addDependency($this->userId,$body),201);if($action==='remove_dependency')return TaskApiResponse::ok($this->app->removeDependency($this->userId,$body));if(str_starts_with($action,'recurrence_')){if($this->recurrence===null)throw new TaskNotFoundException('not_found');if($action==='recurrence_create')return TaskApiResponse::ok($this->recurrence->recurrenceCreate($this->userId,$body),201);if($action==='recurrence_pause')return TaskApiResponse::ok($this->recurrence->recurrencePause($this->userId,$body));if($action==='recurrence_resume')return TaskApiResponse::ok($this->recurrence->recurrenceResume($this->userId,$body));if($action==='recurrence_cancel')return TaskApiResponse::ok($this->recurrence->recurrenceCancel($this->userId,$body));}throw new TaskNotFoundException('not_found');
  }catch(TaskValidationException|InvalidArgumentException$e){return TaskApiResponse::error($e->getMessage(),422);}catch(TaskNotFoundException$e){return TaskApiResponse::error('not_found',404);}catch(TaskConcurrencyException|TaskTransitionException$e){return TaskApiResponse::error($e->getMessage(),409);}catch(RuntimeException$e){if($e->getMessage()==='csrf_invalid')return TaskApiResponse::error('csrf_invalid',403);error_log('Task API internal error: '.$e->getMessage());return TaskApiResponse::error('internal_error',500);}catch(Throwable$e){error_log('Task API internal error: '.$e->getMessage());return TaskApiResponse::error('internal_error',500);}
 }
}
